48	/// Normalized runtime configuration for the minimal OpenAI-compatible server.
49	#[derive(Educe, Clone, PartialEq, Eq, Serialize)]
50	#[educe(Debug)]
51	pub struct Config {
52	    /// Frontend-to-engine transport setup.
53	    pub transport_mode: TransportMode,
54	    /// Requested frontend-side coordinator behavior.
55	    pub coordinator_mode: CoordinatorMode,
56	    /// Backend model identifier used for engine-core loading.
57	    pub model: String,
58	    /// Model name(s) exposed to clients via the OpenAI API. When non-empty,
59	    /// the first entry is used as the primary ID in responses and all entries
60	    /// are accepted in requests. When empty, falls back to `model`.
61	    pub served_model_name: Vec<String>,
62	    /// HTTP listener setup.
63	    pub listener_mode: HttpListenerMode,
64	    /// Tool-call parser selection.
65	    pub tool_call_parser: ParserSelection,
66	    /// Reasoning parser selection.
67	    pub reasoning_parser: ParserSelection,
68	    /// Chat renderer selection.
69	    pub renderer: RendererSelection,
70	    /// Disable frontend-side multimodal preprocessing and render the model as
71	    /// language-only.
72	    pub language_model_only: bool,
73	    /// Server-default chat template override, as a file path or inline
74	    /// template.
75	    pub chat_template: Option<String>,
76	    /// Server-default keyword arguments merged into every chat-template render.
77	    pub default_chat_template_kwargs: Option<HashMap<String, Value>>,
78	    /// How to serialize `message.content` for chat-template rendering.
79	    pub chat_template_content_format: ChatTemplateContentFormatOption,
80	    /// Optional maximum number of top log probabilities accepted by the
81	    /// frontend. `None` delegates to the text layer default.
82	    pub max_logprobs: Option<i32>,
83	    /// HTTP/API-server behavior switches.
84	    pub api_server_options: ApiServerOptions,
85	    /// API keys accepted as bearer tokens for guarded routes.
86	    #[serde(skip_serializing)]
87	    #[educe(Debug(method(fmt_redacted_api_keys)))]
88	    pub api_keys: Vec<String>,
89	    /// When `true`, suppress periodic stats logging (throughput, queue depth,
90	    /// cache usage).
91	    pub disable_log_stats: bool,
92	    /// TCP port for the gRPC Generate service. When `None`, no gRPC server is
93	    /// started.
94	    pub grpc_port: Option<u16>,
95	    /// Maximum time to wait for active HTTP/gRPC requests to drain on shutdown.
96	    pub shutdown_timeout: Duration,
97	}
