147	impl fmt::Debug for RedactedApiKeys<'_> {
148	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
149	        if self.0.is_empty() {
150	            f.debug_list().finish()
151	        } else {
152	            write!(f, "[<redacted>; {}]", self.0.len())
153	        }
154	    }
155	}
156	
157	fn fmt_redacted_api_keys(api_keys: &[String], f: &mut fmt::Formatter<'_>) -> fmt::Result {
158	    fmt::Debug::fmt(&RedactedApiKeys(api_keys), f)
159	}
