38	/// Resolve the public model names accepted by the frontend.
39	fn effective_served_model_names(model: &str, served_model_name: &[String]) -> Vec<String> {
40	    if served_model_name.is_empty() {
41	        vec![model.to_string()]
42	    } else {
43	        served_model_name.to_vec()
44	    }
45	}
