47	/// Build the shared application state for one configured model and one engine
48	/// client.
49	async fn build_state(config: &Config) -> Result<Arc<AppState>> {
50	    // If no served names are specified, fall back to the backend model path so
51	    // that the API always has at least one valid model ID. Use the same primary
52	    // public name for frontend-side metrics labels.
53	    let served_model_names = effective_served_model_names(&config.model, &config.served_model_name);
54	    let metrics_model_name = served_model_names[0].clone();
55	
56	    // Load both backends from the same model metadata so they stay in sync.
57	    let loaded = load_model_backends(
58	        &config.model,
59	        LoadModelBackendsOptions {
60	            renderer: config.renderer,
61	            language_model_only: config.language_model_only,
62	            chat_template: config.chat_template.clone(),
63	            chat_template_content_format: config.chat_template_content_format,
64	            default_chat_template_kwargs: config
65	                .default_chat_template_kwargs
66	                .clone()
67	                .unwrap_or_default(),
68	        },
69	    )
70	    .await
71	    .context("failed to create chat/text backends")?;
72	    let text_backend = loaded.text_backend;
73	    let chat_backend = loaded.chat_backend;
74	
75	    let coordinator_mode = config.effective_coordinator_mode(text_backend.is_moe());
76	    info!(
77	        engine_count = config.engine_count(),
78	        model_is_moe = text_backend.is_moe(),
79	        ?coordinator_mode,
80	        "resolved coordinator mode"
81	    );
82	
83	    let client = EngineCoreClient::connect(EngineCoreClientConfig {
84	        transport_mode: config.transport_mode.clone(),
85	        coordinator_mode,
86	        model_name: metrics_model_name,
87	        client_index: 0,
88	    })
89	    .await
90	    .context("failed to connect to engine core")?;
91	
92	    let llm = Llm::new(client).with_log_stats(!config.disable_log_stats);
93	    let text = TextLlm::new(llm, text_backend).with_max_logprobs(config.max_logprobs);
94	
95	    let chat = ChatLlm::new(text, chat_backend)
96	        .with_tool_call_parser(config.tool_call_parser.clone())
97	        .with_reasoning_parser(config.reasoning_parser.clone());
98	
99	    Ok(Arc::new(
100	        AppState::new(served_model_names, chat)
101	            .with_api_server_options(config.api_server_options)
102	            .with_server_info(ServerInfoSnapshot::from_config(config))
103	            .with_api_keys(config.api_keys.clone()),
104	    ))
105	}
