15	/// Authenticate guarded HTTP routes with an OpenAI-compatible bearer token.
16	///
17	/// Mirrors Python `AuthenticationMiddleware`: OPTIONS requests and non-guarded
18	/// helper endpoints such as `/health` are allowed through without a token.
19	pub async fn authenticate_api_key(
20	    State(state): State<Arc<AppState>>,
21	    req: Request,
22	    next: Next,
23	) -> Response {
24	    if req.method() == Method::OPTIONS || !requires_auth(req.uri().path()) {
25	        return next.run(req).await;
26	    }
27	
28	    if verify_token(req.headers().get(AUTHORIZATION), state.api_key_hashes()) {
29	        return next.run(req).await;
30	    }
31	
32	    (
33	        StatusCode::UNAUTHORIZED,
34	        Json(json!({ "error": "Unauthorized" })),
35	    )
36	        .into_response()
37	}
38	
39	fn requires_auth(path: &str) -> bool {
40	    GUARDED_PREFIXES.iter().any(|prefix| path.starts_with(prefix))
41	}
42	
43	fn verify_token(authorization: Option<&HeaderValue>, api_key_hashes: &[ApiKeyHash]) -> bool {
44	    let Some(authorization) = authorization else {
45	        return false;
46	    };
47	    let Ok(authorization) = authorization.to_str() else {
48	        return false;
49	    };
50	    let Some((scheme, token)) = authorization.split_once(' ') else {
51	        return false;
52	    };
53	    if !scheme.eq_ignore_ascii_case("bearer") {
54	        return false;
55	    }
56	
57	    let token_hash = hash_api_key(token);
58	    let mut token_match = false;
59	    for api_key_hash in api_key_hashes {
60	        token_match |= constant_time_eq(&token_hash, api_key_hash);
61	    }
62	    token_match
63	}
64	
65	fn constant_time_eq(left: &ApiKeyHash, right: &ApiKeyHash) -> bool {
66	    use subtle::ConstantTimeEq;
67	
68	    bool::from(left.ct_eq(right))
69	}
