61	fn build_router_with_options(
62	    state: Arc<AppState>,
63	    dev_mode_enabled: bool,
64	    runtime_lora_updating_enabled: bool,
65	) -> Router {
66	    let mut router = Router::new()
67	        // Health & monitoring
68	        .route("/health", get(health::health))
69	        .route("/metrics", get(metrics::scrape))
70	        .route("/load", get(load::load))
71	        .route("/version", get(version::version))
72	        // OpenAI-compatible endpoints
73	        .route("/v1/models", get(openai::list_models))
74	        .route("/v1/completions", post(openai::completions))
75	        .route("/v1/chat/completions", post(openai::chat_completions))
76	        // vLLM specific endpoints
77	        .route("/tokenize", post(tokenize::tokenize))
78	        .route("/detokenize", post(tokenize::detokenize))
79	        .route("/inference/v1/generate", post(inference::generate));
80	
81	    if runtime_lora_updating_enabled {
82	        router = router
83	            .route("/v1/load_lora_adapter", post(lora::load_lora_adapter))
84	            .route("/v1/unload_lora_adapter", post(lora::unload_lora_adapter));
85	    }
86	
87	    if dev_mode_enabled {
88	        // Development-only
89	        router = router
90	            .route("/reset_prefix_cache", post(cache::reset_prefix_cache))
91	            .route("/reset_mm_cache", post(cache::reset_mm_cache))
92	            .route("/reset_encoder_cache", post(cache::reset_encoder_cache))
93	            .route("/collective_rpc", post(collective_rpc::collective_rpc))
94	            .route("/sleep", post(sleep::sleep))
95	            .route("/wake_up", post(sleep::wake_up))
96	            .route("/is_sleeping", get(sleep::is_sleeping))
97	            .route("/pause", post(pause::pause))
98	            .route("/resume", post(pause::resume))
99	            .route("/is_paused", get(pause::is_paused))
100	            .route("/server_info", get(server_info::server_info))
101	    }
102	
103	    let enable_request_id_headers = state.api_server_options.enable_request_id_headers;
104	    let enable_api_key_auth = state.has_api_keys();
105	    let mut router = router
106	        .with_state(state.clone())
107	        .layer(from_fn_with_state(
108	            state.clone(),
109	            middleware::track_server_load,
110	        ))
111	        .layer(from_fn(middleware::track_http_metrics));
112	
113	    if enable_api_key_auth {
114	        router = router.layer(from_fn_with_state(
115	            state.clone(),
116	            middleware::authenticate_api_key,
117	        ));
118	    }
119	
120	    // Later layers wrap earlier ones. Keep tracing outside auth so rejected
121	    // requests are visible, while metrics/load only see authenticated traffic.
122	    router = router.layer(TraceLayer::new_for_http());
123	
124	    if enable_request_id_headers {
125	        router = router.layer(from_fn(middleware::set_request_id_header));
126	    }
127	
128	    router
129	}
