1	//! CORS support mirroring Python's Starlette `CORSMiddleware`.
2	//!
3	//! Built on `tower_http::cors::CorsLayer`, configured to reproduce Starlette's
4	//! `CORSMiddleware` behavior for the `--allowed-origins` / `--allowed-methods` /
5	//! `--allowed-headers` / `--allow-credentials` settings. Two intentional
6	//! behavioral differences remain, both invisible to real clients:
7	//!
8	//! - A rejected preflight returns `200` (empty) rather than Starlette's
9	//!   `400 "Disallowed CORS ..."`. The browser denies the request either way
10	//!   (the disallowed `Access-Control-Allow-*` headers are simply absent), and
11	//!   tower-http makes the preflight reject decision inside its short-circuit,
12	//!   so matching the `400` would mean re-implementing the layer.
13	//! - A bare `OPTIONS` (no `Access-Control-Request-Method`) returns `200`
14	//!   rather than `405`. No real client sends one.
15	
16	use std::time::Duration;
17	
18	use axum::extract::Request;
19	use axum::http::{HeaderName, HeaderValue, Method, header};
20	use axum::middleware::Next;
21	use axum::response::Response;
22	use tower_http::cors::{AllowHeaders, AllowMethods, AllowOrigin, CorsLayer};
23	
24	use crate::config::CorsConfig;
25	
26	/// The method set that `"*"` expands to.
27	const ALL_METHODS: [Method; 7] = [
28	    Method::DELETE,
29	    Method::GET,
30	    Method::HEAD,
31	    Method::OPTIONS,
32	    Method::PATCH,
33	    Method::POST,
34	    Method::PUT,
35	];
36	
37	/// Headers always treated as allowed (the CORS safelist).
38	const SAFELISTED_HEADERS: [&str; 4] = [
39	    "accept",
40	    "accept-language",
41	    "content-language",
42	    "content-type",
43	];
44	
45	fn is_wildcard(values: &[String]) -> bool {
46	    values.iter().any(|value| value == "*")
47	}
48	
49	/// Build a `CorsLayer` from the resolved [`CorsConfig`].
50	///
51	/// Values are assumed valid: [`CorsConfig::validate`] runs at startup before
52	/// the router is built.
53	pub fn cors_layer(cfg: &CorsConfig) -> CorsLayer {
54	    let wildcard_origins = is_wildcard(&cfg.allow_origins);
55	
56	    let allow_origin = if wildcard_origins {
57	        if cfg.allow_credentials {
58	            // `*` with credentials is illegal, so reflect the request origin
59	            // instead; this also avoids tower-http's wildcard+credentials panic.
60	            AllowOrigin::mirror_request()
61	        } else {
62	            AllowOrigin::any()
63	        }
64	    } else {
65	        AllowOrigin::list(
66	            cfg.allow_origins
67	                .iter()
68	                .map(|origin| origin.parse::<HeaderValue>().expect("validated origin"))
69	                .collect::<Vec<_>>(),
70	        )
71	    };
72	
73	    // Expand `*` to an explicit list rather than `Any`, so we emit the method
74	    // names (not `*`) and never hit tower-http's `Any`+credentials panic.
75	    let allow_methods = if is_wildcard(&cfg.allow_methods) {
76	        AllowMethods::list(ALL_METHODS)
77	    } else {
78	        AllowMethods::list(
79	            cfg.allow_methods
80	                .iter()
81	                .map(|method| method.parse::<Method>().expect("validated method"))
82	                .collect::<Vec<_>>(),
83	        )
84	    };
85	
86	    let allow_headers = if is_wildcard(&cfg.allow_headers) {
87	        // `*` mirrors the requested headers.
88	        AllowHeaders::mirror_request()
89	    } else {
90	        // Union the safelisted headers, lowercased and sorted.
91	        let mut names: Vec<String> = SAFELISTED_HEADERS.iter().map(|s| s.to_string()).collect();
92	        names.extend(cfg.allow_headers.iter().map(|h| h.to_ascii_lowercase()));
93	        names.sort();
94	        names.dedup();
95	        AllowHeaders::list(
96	            names
97	                .iter()
98	                .map(|header| header.parse::<HeaderName>().expect("validated header"))
99	                .collect::<Vec<_>>(),
100	        )
101	    };
102	
103	    // Emit `Vary: Origin` only when the allow-origin is dynamic (explicit
104	    // origins, or credentials); the wildcard + no-credentials case emits no
105	    // `Vary` at all, and an empty list disables the header here.
106	    let vary: Vec<HeaderName> = if !wildcard_origins || cfg.allow_credentials {
107	        vec![header::ORIGIN]
108	    } else {
109	        vec![]
110	    };
111	
112	    CorsLayer::new()
113	        .allow_origin(allow_origin)
114	        .allow_methods(allow_methods)
115	        .allow_headers(allow_headers)
116	        .allow_credentials(cfg.allow_credentials)
117	        .max_age(Duration::from_secs(600))
118	        .vary(vary)
119	}
120	
121	/// Strip CORS response headers when the request carried no `Origin`.
122	///
123	/// A request without an `Origin` should carry no CORS headers, but tower-http
124	/// emits `Vary` and `Access-Control-Allow-*` unconditionally. Removing them on
125	/// no-`Origin` requests keeps non-CORS responses (e.g. `/health`, plain `curl`)
126	/// clean.
127	pub async fn strip_cors_on_no_origin(req: Request, next: Next) -> Response {
128	    let had_origin = req.headers().contains_key(header::ORIGIN);
129	    let mut response = next.run(req).await;
130	    if !had_origin {
131	        let headers = response.headers_mut();
132	        headers.remove(header::VARY);
133	        headers.remove(header::ACCESS_CONTROL_ALLOW_ORIGIN);
134	        headers.remove(header::ACCESS_CONTROL_ALLOW_CREDENTIALS);
135	        headers.remove(header::ACCESS_CONTROL_ALLOW_METHODS);
136	        headers.remove(header::ACCESS_CONTROL_ALLOW_HEADERS);
137	        headers.remove(header::ACCESS_CONTROL_MAX_AGE);
138	        headers.remove(header::ACCESS_CONTROL_EXPOSE_HEADERS);
139	    }
140	    response
141	}
