68	fn build_router_with_options(
69	    state: Arc<AppState>,
70	    dev_mode_enabled: bool,
71	    runtime_lora_updating_enabled: bool,
72	) -> Router {
73	    let mut router = Router::new()
74	        // Health & monitoring
75	        .route("/health", get(health::health))
76	        .route("/metrics", get(metrics::scrape))
77	        .route("/load", get(load::load))
78	        .route("/version", get(version::version))
79	        // OpenAI-compatible endpoints
80	        .route("/v1/models", get(openai::list_models))
81	        .route("/v1/completions", post(openai::completions))
82	        .route("/v1/chat/completions", post(openai::chat_completions))
83	        // vLLM specific endpoints
84	        .route("/tokenize", post(tokenize::tokenize))
85	        .route("/detokenize", post(tokenize::detokenize))
86	        .route("/inference/v1/generate", post(inference::generate));
87	
88	    if runtime_lora_updating_enabled {
89	        router = router
90	            .route("/v1/load_lora_adapter", post(lora::load_lora_adapter))
91	            .route("/v1/unload_lora_adapter", post(lora::unload_lora_adapter));
92	    }
93	
94	    if dev_mode_enabled {
95	        // Development-only
96	        router = router
97	            .route("/reset_prefix_cache", post(cache::reset_prefix_cache))
98	            .route("/reset_mm_cache", post(cache::reset_mm_cache))
99	            .route("/reset_encoder_cache", post(cache::reset_encoder_cache))
100	            .route("/collective_rpc", post(collective_rpc::collective_rpc))
101	            .route("/abort_requests", post(abort_requests::abort_requests))
102	            .route("/sleep", post(sleep::sleep))
103	            .route("/wake_up", post(sleep::wake_up))
104	            .route("/is_sleeping", get(sleep::is_sleeping))
105	            .route("/pause", post(pause::pause))
106	            .route("/resume", post(pause::resume))
107	            .route("/is_paused", get(pause::is_paused))
108	            .route("/server_info", get(server_info::server_info))
109	            .route("/get_world_size", get(world_size::get_world_size))
110	    }
111	
112	    if let Some(profiler) = &state.profiler {
113	        warn!(
114	            mode = profiler,
115	            "profiler is enabled in the API server; \
116	             this should only be used for local development",
117	        );
118	        router = router
119	            .route("/start_profile", post(profile::start_profile))
120	            .route("/stop_profile", post(profile::stop_profile));
121	    }
122	
123	    let enable_request_id_headers = state.api_server_options.enable_request_id_headers;
124	    let enable_api_key_auth = state.has_api_keys();
125	    let mut router = router
126	        .with_state(state.clone())
127	        .layer(DefaultBodyLimit::max(DEFAULT_JSON_BODY_LIMIT_BYTES))
128	        .layer(middleware::request_runtime_layer(state.clone()))
129	        .layer(from_fn_with_state(
130	            state.clone(),
131	            middleware::track_server_load,
132	        ))
133	        .layer(from_fn(middleware::track_http_metrics))
134	        .layer(middleware::cors_layer(&state.cors))
135	        .layer(from_fn(middleware::strip_cors_on_no_origin));
136	
137	    if enable_api_key_auth {
138	        router = router.layer(from_fn_with_state(
139	            state.clone(),
140	            middleware::authenticate_api_key,
141	        ));
142	    }
143	
144	    // Later layers wrap earlier ones. Keep tracing outside auth so rejected
145	    // requests are visible, while metrics/load only see authenticated traffic.
146	    router = router.layer(TraceLayer::new_for_http());
147	
148	    if enable_request_id_headers {
149	        router = router.layer(from_fn(middleware::set_request_id_header));
150	    }
151	
152	    router
153	}
